#include <stdlib.h>

int merge(int v[], int ini, int meio, int fim) {
    int n = fim - ini + 1;
    int *aux = malloc((size_t)n * sizeof(int));
    if (aux == NULL) return 0;

    int i = ini, j = meio + 1, k = 0;
    while (i <= meio && j <= fim) {
