```c
static void trocar(int *a, int *b) {
    int tmp = *a;
    *a = *b;
    *b = tmp;
}

int particionar(int v[], int ini, int fim) {
    int pivo = v[fim];
    int i = ini - 1;
    for (int j = ini; j < fim; j++) {
        if (v[j] <= pivo) {
            i++;
            trocar(&v[i], &v[j]);
        }
    }
    trocar(&v[i + 1], &v[fim]);
    return i + 1;
}

void quicksort(int v[], int ini, int fim) {
    if (ini >= fim) return;
    int p = particionar(v, ini, fim);
    quicksort(v, ini, p - 1);
    quicksort(v, p + 1, fim);
}
```

